<script setup lang="ts">
import { t as uiText } from '@/locales'

import {computed,ref,watch} from 'vue'
import {ElMessage} from 'element-plus'
import FixedTableViewport from '@/components/FixedTableViewport/index.vue'
import * as api from '@/api/modules/phoneReference'
import {useUserStore} from '@/stores/user'
import {useCollaborationWorkspace} from '@/stores/collaborationWorkspace'
import type {PhoneBrand} from '@/types/molds'
const props=defineProps<{visible:boolean;keyword?:string}>()
const emit=defineEmits<{changed:[];navigate:[{tab:string;keyword:string;kind?:'code_many_names'|'name_many_codes';phoneModelId?:number}]}>()
const user=useUserStore(),workspace=useCollaborationWorkspace(),data=ref<api.PhoneIssuesPage>(),loading=ref(false),busy=ref(false),error=ref('')
const keyword=ref(props.keyword||''),state=ref<api.PhoneIssueState|'all'>('pending'),page=ref(1),brands=ref<PhoneBrand[]>([])
const rows=computed(()=>data.value?.content||[]),ready=computed(()=>data.value?.canMaintain?data.value.readyItems:[])
const names:Record<api.PhoneIssueState,string>={pending:'需补资料',ready:'依据明确',resolved:'已处理',not_phone:'非手机编码'}
const editor=ref(false),active=ref<api.PhoneIdentityIssue>(),form=ref({codeName:'',brandIds:[] as number[],reason:''}),saveError=ref('')
const mergeVisible=ref(false),mergeForm=ref({source:undefined as number|undefined,target:undefined as number|undefined,reason:''}),mergePlan=ref<api.PhoneBrandMergePlan>(),mergeError=ref('')
let generation=0,mergeGeneration=0
function message(e:unknown){return e instanceof Error?e.message:'操作失败，请重试'}
async function load(){if(!user.token||!props.visible)return;const ticket=++generation,token=user.token;loading.value=true;error.value='';try{const result=await api.getPhoneIdentityIssues({page:page.value,size:50,keyword:keyword.value.trim(),state:state.value});if(ticket===generation&&token===user.token)data.value=result}catch(e){if(ticket===generation&&token===user.token)error.value=message(e)}finally{if(ticket===generation)loading.value=false}}
function search(){page.value=1;void load()}
async function resolve(items=ready.value){if(busy.value||!items.length)return;const token=user.token;busy.value=true;error.value='';try{await api.resolvePhoneIdentityIssues(items,'按已有编码、明确原文及可信来源集中核对；保留原码、历史快照、实物适配和人工节点');if(token!==user.token)return;workspace.changed();emit('changed');await load();ElMessage.success(uiText('明确项已处理，未新增模具、库存或累计产量'))}catch(e){if(token===user.token)error.value=message(e)}finally{busy.value=false}}
async function loadBrands(){const token=user.token;const result=await api.getPhoneSelectionBrands();if(token===user.token)brands.value=result}
async function edit(row:api.PhoneIdentityIssue){active.value=row;saveError.value='';form.value={codeName:row.suggestedName||row.title,brandIds:[...(row.suggestedBrandIds||row.brandIds||[])],reason:''};editor.value=true;try{await loadBrands()}catch(e){saveError.value=message(e)}}
async function save(){const row=active.value,token=user.token;if(!row?.codeItemId||!form.value.codeName.trim()||!form.value.brandIds.length||!form.value.reason.trim()){saveError.value='请先选择品牌，并补齐完整型号和核对依据';return}busy.value=true;saveError.value='';try{await api.editPhoneIdentityIssue({codeItemId:row.codeItemId,sourceDigest:row.sourceDigest,codeName:form.value.codeName.trim(),brandIds:form.value.brandIds,reason:form.value.reason.trim()});if(token!==user.token)return;editor.value=false;workspace.changed();emit('changed');await load();ElMessage.success(uiText('资料已保存，原编码保持不变'))}catch(e){if(token===user.token)saveError.value=message(e)}finally{busy.value=false}}
function navigate(row:api.PhoneIdentityIssue){emit('navigate',{tab:row.editTab||'groups',keyword:row.historyKey||row.phoneCodes[0]||'',kind:row.historyKind,...(row.focusPhoneModelId?{phoneModelId:row.focusPhoneModelId}:{})})}
async function openMerge(){mergeForm.value={source:undefined,target:undefined,reason:''};mergePlan.value=undefined;mergeError.value='';mergeVisible.value=true;try{await loadBrands()}catch(e){mergeError.value=message(e)}}
async function previewMerge(){if(!mergeForm.value.source||!mergeForm.value.target||busy.value)return;const token=user.token,ticket=++mergeGeneration;busy.value=true;mergeError.value='';try{const plan=await api.previewPhoneBrandMerge(mergeForm.value.source,mergeForm.value.target);if(token===user.token&&ticket===mergeGeneration&&mergeVisible.value)mergePlan.value=plan}catch(e){if(token===user.token)mergeError.value=message(e)}finally{busy.value=false}}
async function commitMerge(){const plan=mergePlan.value,token=user.token;if(!plan||plan.blockers.length||!mergeForm.value.reason.trim()){mergeError.value='请先核对预览、处理阻止项并填写品牌对应依据';return}busy.value=true;mergeError.value='';try{await api.mergePhoneBrands({sourceBrandId:plan.source.brandId,targetBrandId:plan.target.brandId,sourceDigest:plan.sourceDigest,reason:mergeForm.value.reason.trim()});if(token!==user.token)return;mergeVisible.value=false;workspace.changed();emit('changed');await load();ElMessage.success(uiText('品牌及引用已统一，原手机和业务ID保留'))}catch(e){if(token===user.token)mergeError.value=message(e)}finally{busy.value=false}}
watch([()=>mergeForm.value.source,()=>mergeForm.value.target],()=>{mergeGeneration++;mergePlan.value=undefined},{flush:'sync'})
watch(()=>props.visible,v=>{if(v)void load();else{generation++;editor.value=false;mergeVisible.value=false}},{immediate:true})
watch(()=>props.keyword,v=>{keyword.value=v||'';search()})
watch(()=>user.token,()=>{generation++;data.value=undefined;brands.value=[];editor.value=false;mergeVisible.value=false})
</script>
<template>
  <section class="identity-issues" :aria-label='uiText("手机资料集中处理")'>
    <div class="issue-controls"><div class="issue-tools"><el-input v-model="keyword" size="small" clearable :aria-label='uiText("手机资料问题关键词")' :placeholder='uiText("手机 / 四位编码 / 产品款式 / 缺项")' @keyup.enter="search"/><el-select v-model="state" size="small" :aria-label='uiText("手机资料处理状态")' @change="search"><el-option value="pending" :label='uiText("需处理（含明确项）")'/><el-option value="ready" :label='uiText("依据明确，可处理")'/><el-option value="resolved" :label='uiText("已处理与依据")'/><el-option value="not_phone" :label='uiText("非手机业务编码")'/><el-option value="all" :label='uiText("全部")'/></el-select><el-button size="small" @click="search">{{ uiText("查询") }}</el-button><el-button size="small" @click="load">{{ uiText("刷新") }}</el-button></div>
    <div class="issue-summary"><span>{{ uiText("需补资料 ") }}{{data?.summary.pending||0}}{{ uiText(" · 明确项 ") }}{{data?.summary.ready||0}}{{ uiText(" · 已处理 ") }}{{data?.summary.resolved||0}}{{ uiText(" · 非手机 ") }}{{data?.summary.not_phone||0}}</span><div v-if="data?.canMaintain"><el-button size="small" :disabled="!ready.length" :loading="busy" @click="resolve()">{{ uiText("一键处理明确项") }}{{ready.length?`（${ready.length}）`:''}}</el-button><el-button size="small" :disabled="busy" @click="openMerge">{{ uiText("统一重复品牌") }}</el-button></div></div>
    </div><el-alert v-if="error" type="error" :closable="false" :title="error"/>
    <FixedTableViewport fill :refresh-key="rows"><div class="issue-list" role="table" :aria-label='uiText("手机品牌及型号问题")' v-loading="loading"><div class="issue-row issue-heading" role="row"><span role="columnheader">{{ uiText("手机／编码 · 产品范围") }}</span><span role="columnheader">{{ uiText("具体缺项、依据及候选") }}</span><span role="columnheader">{{ uiText("办理入口") }}</span></div><div class="issue-body" role="rowgroup" tabindex="0">
      <article v-for="row in rows" :key="row.key" class="issue-row issue-record" role="row"><div role="cell"><strong>{{row.phoneCodes.slice(0,4).join(' / ')}}{{row.phoneCodes.length>4?uiText(' 等{value0}个编码',{value0:(row.phoneCodes.length)}):''}}</strong><span class="issue-model">{{row.modelNames[0]||row.title}}</span><small v-if="row.productNames?.length">{{row.productNames.join('、')}}</small></div><div role="cell"><el-tag size="small" :type="row.state==='ready'?'success':row.state==='pending'?'warning':'info'">{{names[row.state]}}</el-tag><span v-if="row.state==='pending'" class="missing">{{row.missingFields?.join('；')}}</span><details><summary>{{ uiText("完整型号／依据") }}</summary><p>{{row.reviewReason||row.reason}}</p><p v-if="row.referenceCount">{{ uiText("共 ") }}{{row.referenceCount}}{{ uiText(" 条来源，按本组一次处理") }}</p><p v-for="name in row.modelNames" :key="name">{{name}}</p><p v-if="row.productNames?.length">{{ uiText("产品：") }}{{row.productNames.join('、')}}</p><p v-if="row.phoneModelIds?.length">{{ uiText("标准成员 ID：") }}{{row.phoneModelIds.join('、')}}</p><p v-for="line in row.evidence" :key="line">{{line}}</p><p v-if="row.reviewedAt">{{row.reviewedBy}} · {{row.reviewedAt}}</p></details></div><div class="issue-actions" role="cell"><el-button v-if="row.state==='ready'&&row.canResolve" link :disabled="busy" @click="resolve([{key:row.key,sourceDigest:row.sourceDigest}])">{{ uiText("按依据处理本组") }}</el-button><el-button v-if="row.codeItemId&&row.canResolve&&['pending','ready'].includes(row.state)" link :disabled="busy" @click="edit(row)">{{ uiText("补名称／品牌") }}</el-button><el-button link @click="navigate(row)">{{row.editTab==='review'?uiText('打开历史核对'):row.editTab==='phones'?uiText('补品牌／型号'):uiText('查看原编码')}}</el-button></div></article>
      <el-empty v-if="!rows.length&&!loading" :description='uiText("当前筛选没有待处理资料")' :image-size="60"/>
    </div></div></FixedTableViewport>
    <el-pagination size="small" v-model:current-page="page" :page-size="50" :total="data?.totalElements||0" layout="total,prev,pager,next" @current-change="load"/>
    <el-dialog v-model="editor" append-to-body :title='uiText("补齐手机名称与品牌")' width="min(620px,95vw)" :close-on-click-modal="false"><p>{{ uiText("原编码 ") }}{{active?.phoneCodes.join(' / ')}} · {{active?.title}}</p><el-alert v-if="saveError" :title="saveError" type="error" :closable="false"/><el-form label-position="top" size="small" :disabled="busy"><el-form-item :label='uiText("先选择明确品牌")'><el-select v-model="form.brandIds" multiple filterable :aria-label='uiText("补资料品牌")'><el-option v-for="brand in brands" :key="brand.brandId" :value="brand.brandId" :label="brand.name" :disabled="brand.status!=='enabled'"/></el-select></el-form-item><el-form-item :label='uiText("完整型号名称（组合名称保留）")'><el-input v-model="form.codeName" maxlength="128" :aria-label='uiText("补资料完整型号")'/></el-form-item><el-form-item :label='uiText("核对依据")'><el-input v-model="form.reason" type="textarea" :rows="3" maxlength="1000" :placeholder='uiText("原始资料、来源记录或明确的品牌／型号说明")' :aria-label='uiText("补资料核对依据")'/></el-form-item></el-form><template #footer><el-button @click="editor=false">{{ uiText("取消") }}</el-button><el-button type="primary" :loading="busy" @click="save">{{ uiText("保存并重新核对") }}</el-button></template></el-dialog>
    <el-dialog v-model="mergeVisible" append-to-body :title='uiText("统一已核实的重复品牌")' width="min(700px,95vw)" :close-on-click-modal="false"><el-alert v-if="mergeError" :title="mergeError" type="error" :closable="false"/><el-form label-position="top" size="small" :disabled="busy"><el-form-item :label='uiText("将此品牌的引用归入目标品牌")'><el-select v-model="mergeForm.source" filterable :aria-label='uiText("待统一品牌")'><el-option v-for="brand in brands.filter(b=>b.status==='enabled')" :key="brand.brandId" :value="brand.brandId" :label="brand.name"/></el-select></el-form-item><el-form-item :label='uiText("保留的目标品牌")'><el-select v-model="mergeForm.target" filterable :aria-label='uiText("保留目标品牌")'><el-option v-for="brand in brands.filter(b=>b.status==='enabled')" :key="brand.brandId" :value="brand.brandId" :label="brand.name" :disabled="brand.brandId===mergeForm.source"/></el-select></el-form-item><el-button :disabled="!mergeForm.source||!mergeForm.target" @click="previewMerge">{{ uiText("预览关联范围") }}</el-button><template v-if="mergePlan"><p>{{mergePlan.source.name}} → {{mergePlan.target.name}} · {{mergePlan.phoneModelIds.length}}{{ uiText(" 个成员统一品牌 · ") }}{{mergePlan.retiredDuplicatePhoneModelIds?.length||0}}{{ uiText(" 个无引用同码同名旧成员停用（保留ID） · ") }}{{mergePlan.phoneCodes.length}}{{ uiText(" 个编码 · ") }}{{mergePlan.items.length}}{{ uiText(" 个档案引用") }}</p><p>{{mergePlan.phoneCodes.join(' / ')}}</p><el-alert v-for="blocker in mergePlan.blockers" :key="blocker" :title="blocker" type="warning" :closable="false"/><el-form-item :label='uiText("品牌对应依据")'><el-input v-model="mergeForm.reason" type="textarea" :rows="3" maxlength="1000" :placeholder='uiText("明确说明两条来源为什么属于同一品牌；不能只因名称相近或共码合并")'/></el-form-item></template></el-form><template #footer><el-button @click="mergeVisible=false">{{ uiText("取消") }}</el-button><el-button type="primary" :loading="busy" :disabled="!mergePlan||!!mergePlan.blockers.length" @click="commitMerge">{{ uiText("按预览统一引用") }}</el-button></template></el-dialog>
  </section>
</template>
<style scoped>
.identity-issues{display:flex;flex:1;flex-direction:column;min-width:0;min-height:0;gap:6px;font-size:12px;container-type:inline-size;--el-font-size-base:12px}.issue-controls{display:flex;flex-wrap:wrap;align-items:center;gap:6px}.issue-controls>.issue-tools{flex:1;min-width:min(100%,500px)}.issue-controls>.issue-summary{flex:none}.issue-tools,.issue-summary,.issue-summary>div{display:flex;align-items:center;flex-wrap:wrap;gap:6px;flex:none}.issue-tools .el-input{flex:1;min-width:180px}.issue-tools .el-select{width:190px}.issue-summary{justify-content:space-between;color:#5c6e83}.issue-list{height:100%;min-height:0;display:flex;flex-direction:column;overflow:hidden;border:1px solid #e4eaf2;border-radius:4px}.issue-body{flex:1;min-height:0;overflow-y:auto;overflow-x:hidden}.issue-row{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,2fr) 170px;gap:8px;padding:3px 8px;line-height:18px;align-items:start;overflow-wrap:anywhere}.issue-row>div{min-width:0}.issue-heading{flex:none;background:#f2f5fa;color:#61758e}.issue-record{min-height:42px;box-sizing:border-box;border-bottom:1px solid #e4eaf2}.issue-record:nth-child(even){background:#fafbfe}p{margin:2px 0;white-space:pre-wrap}small{display:block;color:#6d7e91;font-size:12px;line-height:18px}.missing{margin-left:6px;color:#97611d}.issue-actions{display:flex;flex-direction:row;flex-wrap:wrap;align-items:flex-start;gap:3px}.issue-actions .el-button+.el-button{margin-left:0}.issue-actions .el-button{white-space:normal;text-align:left;height:auto;min-height:24px;line-height:18px;padding:0}.el-pagination{justify-content:flex-end;flex:none}summary{cursor:pointer;color:#2e6cbd;font-size:12px}details{display:inline;margin-left:6px}details[open]{display:block;margin-left:0}summary{display:inline;list-style:none}.issue-model{margin-left:6px}.identity-issues :deep(.el-button){font-size:12px}.el-select{width:100%}.identity-issues :deep(.el-button:not(.is-link)){height:28px}.identity-issues :deep(.el-dialog__title){font-size:16px}
@container(max-width:680px){.issue-heading{display:none}.issue-row{grid-template-columns:minmax(0,1fr);gap:4px}.issue-actions{flex-direction:row;flex-wrap:wrap;gap:8px}.issue-tools .el-select{flex:1;min-width:170px}.issue-tools .el-input{flex-basis:100%}}
</style>
